@isTest
private class RenewalServiceTest {

    @isTest
    static void itCreatesRenewalsOnlyForClosedWonOpportunities() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        Id wonId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id lostId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id accountId = fflib_IDGenerator.generate(Account.SObjectType);
        Id ownerId = fflib_IDGenerator.generate(User.SObjectType);

        Opportunity won = new Opportunity(
            Id = wonId,
            Name = 'Big Deal',
            AccountId = accountId,
            OwnerId = ownerId,
            StageName = 'Closed Won',
            CloseDate = Date.newInstance(2024, 1, 15),
            Amount = 1000
        );

        Opportunity lost = new Opportunity(
            Id = lostId,
            Name = 'Lost Deal',
            AccountId = accountId,
            OwnerId = ownerId,
            StageName = 'Closed Lost',
            CloseDate = Date.newInstance(2024, 1, 15),
            Amount = 500
        );

        Set<Id> opportunityIds = new Set<Id>{ wonId, lostId };

        mocks.startStubbing();
        mocks.when(selectorMock.selectById((Set<Id>) fflib_Match.anyObject()))
            .thenReturn(new List<Opportunity>{ won, lost });
        mocks.stopStubbing();

        Test.startTest();
        RenewalService.createRenewals(opportunityIds);
        Test.stopTest();

        fflib_ArgumentCaptor renewalCaptor = fflib_ArgumentCaptor.forClass(Opportunity.class);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerNew((SObject) renewalCaptor.capture());

        Opportunity capturedRenewal = (Opportunity) renewalCaptor.getValue();
        System.assertEquals('Big Deal - Renewal', capturedRenewal.Name);
        System.assertEquals(accountId, capturedRenewal.AccountId);
        System.assertEquals('Prospecting', capturedRenewal.StageName);
        System.assertEquals(Date.newInstance(2025, 1, 15), capturedRenewal.CloseDate);
        System.assertEquals(1050.00, capturedRenewal.Amount);

        fflib_ArgumentCaptor taskCaptor = fflib_ArgumentCaptor.forClass(Task.class);
        fflib_ArgumentCaptor fieldCaptor = fflib_ArgumentCaptor.forClass(Schema.SObjectField.class);
        fflib_ArgumentCaptor relatedToCaptor = fflib_ArgumentCaptor.forClass(SObject.class);

