            (SObject) taskCaptor.capture(),
            (Schema.SObjectField) fieldCaptor.capture(),
            (SObject) relatedToCaptor.capture()
        );

        Task capturedTask = (Task) taskCaptor.getValue();
        System.assertEquals('Prepare renewal for Big Deal', capturedTask.Subject);
        System.assertEquals(ownerId, capturedTask.OwnerId);
        System.assertEquals(Date.newInstance(2024, 11, 16), capturedTask.ActivityDate);

        System.assertEquals(Task.WhatId, fieldCaptor.getValue());
        System.assertEquals(capturedRenewal, relatedToCaptor.getValue());

        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).commitWork();
