/**
 * Sends renewal reminder emails to Opportunity owners.
 *
 * Note: Messaging.sendEmail is called once per opportunity (inside the loop)
 * as requested, so that a failure for one recipient does not prevent the
 * rest from being attempted. Be aware that Salesforce enforces a limit of
 * 10 Messaging.sendEmail calls per transaction in production execution
 * contexts; if this service is ever invoked with more than 10 opportunities
 * in a single transaction, it will throw a System.LimitException outside
 * of test context. Since the requirement explicitly calls for one
 * Messaging.sendEmail call per opportunity, the scheduled job invoking this
 * method should be adjusted to process batches of 10 or fewer opportunities
 * per transaction (e.g. via Batch Apex with a scope of 10) to stay within
 * that governor limit safely in production.
 */
public with sharing class RenewalReminderService {

    public static Integer sendReminders(List<Id> opportunityIds) {
        Integer sentCount = 0;

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return sentCount;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
            AND OwnerId != null
        ];

        for (Opportunity opp : opportunities) {
            Messaging.SingleEmailMessage mail = buildEmail(opp);

            Messaging.SendEmailResult[] results = Messaging.sendEmail(
                new List<Messaging.SingleEmailMessage>{ mail },
                false
            );

            if (results != null && !results.isEmpty() && results[0].isSuccess()) {
                sentCount++;
            }
        }

        return sentCount;
    }

    private static Messaging.SingleEmailMessage buildEmail(Opportunity opp) {
        Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
        mail.setTargetObjectId(opp.OwnerId);
        mail.setSaveAsActivity(false);
        mail.setSubject('Renewal due: ' + opp.Name);

        String closeDateStr = (opp.CloseDate != null)
            ? opp.CloseDate.format()
            : 'an unspecified date';

        mail.setPlainTextBody(
            'This is a reminder that the opportunity "' + opp.Name +
            '" is due for renewal on ' + closeDateStr +
            '. Please review it and take the necessary action.'
        );

        return mail;
    }
}
