public inherited sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MSG =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = (List<Contact>) triggerNew;
        evaluate(contacts, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> contacts = (List<Contact>) triggerNew;
        List<Contact> oldContacts = (List<Contact>) triggerOld;
        evaluate(contacts, oldContacts);
    }

    private void evaluate(List<Contact> contacts, List<Contact> oldContacts) {
        Map<Id, Contact> oldById = new Map<Id, Contact>();
        if (oldContacts != null) {
            for (Contact c : oldContacts) {
                oldById.put(c.Id, c);
            }
        }

        Set<Id> accountIds = new Set<Id>();
        List<Contact> candidates = new List<Contact>();

        for (Contact c : contacts) {
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }
            if (oldContacts != null) {
                Contact oldC = oldById.get(c.Id);
                if (oldC != null && oldC.Email == c.Email && oldC.AccountId == c.AccountId) {
                    continue;
                }
            }
            accountIds.add(c.AccountId);
            candidates.add(c);
        }

        if (candidates.isEmpty()) {
            return;
        }

        Map<Id, Set<String>> accountIdToEmails = new Map<Id, Set<String>>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds AND Email != null
        ]) {
            Set<String> emails = accountIdToEmails.get(existing.AccountId);
            if (emails == null) {
                emails = new Set<String>();
                accountIdToEmails.put(existing.AccountId, emails);
            }
            emails.add(existing.Email.toLowerCase());
        }

        // Remove the current records being updated from the "existing" picture,
        // since they are represented by candidates themselves.
        if (!oldById.isEmpty()) {
            for (Contact c : candidates) {
                Contact oldC = oldById.get(c.Id);
                if (oldC != null && oldC.AccountId != null && oldC.Email != null) {
                    Set<String> emails = accountIdToEmails.get(oldC.AccountId);
                    if (emails != null) {
                        emails.remove(oldC.Email.toLowerCase());
                    }
                }
            }
        }

        Map<Id, Set<String>> seenInBatch = new Map<Id, Set<String>>();

        for (Contact c : candidates) {
            Set<String> dbEmails = accountIdToEmails.get(c.AccountId);
            String emailLower = c.Email.toLowerCase();

            Set<String> seen = seenInBatch.get(c.AccountId);
            if (seen == null) {
                seen = new Set<String>();
                seenInBatch.put(c.AccountId, seen);
            }

            Boolean conflict = false;
            if (dbEmails != null && dbEmails.contains(emailLower)) {
                conflict = true;
            }
            if (seen.contains(emailLower)) {
                conflict = true;
            }

            if (conflict) {
                c.addError(ERROR_MSG);
            } else {
                seen.add(emailLower);
            }
        }
    }
}
